const UI_I18N_SOURCES = Object.keys(UI_I18N_PHRASES.en || {})
export function uiPhraseKey(value = '') { return `ui.${String(value).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')}` }
export function buildTranslationCatalog() {
  return Object.fromEntries(['en','ar','fa','he'].map(lang => [lang, { ...(CORE_I18N_TRANSLATIONS[lang] || {}), ...Object.fromEntries(UI_I18N_SOURCES.map(source => [uiPhraseKey(source), (lang === 'en' ? source : UI_I18N_PHRASES[lang]?.[source]) || source])) }]))
}
export function uiLanguage(settings) { return settings?.localization?.defaultLanguage || settings?.language || 'en' }
function uiPhraseMap(settings, lang = uiLanguage(settings)) {
  const catalog = settings?.localization?.translations || {}
  const direct = UI_I18N_PHRASES[lang] || {}
  return Object.fromEntries(UI_I18N_SOURCES.map(source => [source, catalog?.[lang]?.[uiPhraseKey(source)] || direct[source] || source]))
}
export function canonicalUiPhrase(value = '') {
  const text = String(value).trim().replace(/\s+/g, ' ')
  if (!text) return ''
  if (UI_I18N_PHRASES.en?.[text]) return text
  for (const source of UI_I18N_SOURCES) for (const lang of Object.keys(UI_I18N_PHRASES)) if (UI_I18N_PHRASES[lang]?.[source] === text) return source
  return text
}
export function translateUiText(settings, value = '') {
  const raw = String(value)
  const trimmed = raw.trim().replace(/\s+/g, ' ')
  if (!trimmed) return raw
  const lang = uiLanguage(settings)
  if (lang === 'en') {
    const canonical = canonicalUiPhrase(trimmed)
    return raw.replace(trimmed, canonical)
  }
  const map = uiPhraseMap(settings, lang)
  const exact = map[canonicalUiPhrase(trimmed)]
  if (exact) return raw.replace(trimmed, exact)
  let out = raw
  const candidates = [...UI_I18N_SOURCES].filter(source => source.length > 10).sort((a, b) => b.length - a.length)
  for (const source of candidates) {
    const target = map[source] || source
    const variants = [source, ...Object.keys(UI_I18N_PHRASES).map(l => UI_I18N_PHRASES[l]?.[source]).filter(Boolean)]
    for (const variant of variants) if (variant && out.includes(variant)) out = out.split(variant).join(target)
  }
  return out
}
